#include <stdio.h>
/* ex02：单缓冲 / 双缓冲 的处理时间
 * 经典模型（王道/汤小丹）：一块数据的传输时间 T、CPU 处理时间 C、缓冲区搬移到工作区时间 M(取 0)
 *   无缓冲：设备装填与 CPU 处理完全串行 -> 每块 T+C
 *   单缓冲：缓冲区搬空后设备立刻装填，与 CPU 处理重叠 -> 每块 max(C,T)
 *   双缓冲：设备写 A 的同时 CPU 处理 B，重叠更彻底 -> 首块 T + (n-1) 块 max(C,T) + 收尾 C
 * 关键结论：缓冲只在 T>C 时有效；一旦 CPU 成为瓶颈（C>T），加缓冲没有收益。*/
int main(void) {
    int    n = 10;
    double T = 8.0;      /* 设备传一块到缓冲区：8ms */
    double C = 5.0;      /* CPU 处理一块：5ms */
    double C2 = 12.0;    /* 反例：CPU 更慢，成为瓶颈 */

    double single = T + n * (C > T ? C : T);
    double dual   = T + (n - 1) * (C > T ? C : T) + C;
    double single2 = T + n * (C2 > T ? C2 : T);
    double dual2   = T + (n - 1) * (C2 > T ? C2 : T) + C2;

    printf("块数=%d  传输T=%.0fms  处理C=%.0fms\n", n, T, C);
    printf("------------------------------------------------------------\n");
    printf("%-16s %-14s %s\n", "策略", "总时间(ms)", "瓶颈");
    printf("%-16s %-14.1f %s\n", "无缓冲(全串行)", n * (T + C), "T+C 全串行，最慢");
    printf("%-16s %-14.1f %s\n", "单缓冲", single, C > T ? "CPU 是瓶颈(C>T)" : "I/O 是瓶颈(T>C)");
    printf("%-16s %-14.1f %s\n", "双缓冲", dual, C > T ? "CPU 是瓶颈(C>T)" : "I/O 是瓶颈(T>C)");
    printf("------------------------------------------------------------\n");
    printf("双缓冲比单缓冲快 %.1f%%（本例 T>C，I/O 主导，重叠已接近饱和，提升有限）\n",
           100.0 * (single - dual) / single);
    printf("\n反例：把 C 改成 %.0fms（CPU 更慢、成为瓶颈）\n", C2);
    printf("  单缓冲=%.1f  双缓冲=%.1f  -> %s\n", single2, dual2,
           (single2 - dual2) < 0.05 ? "两者相同" : "双缓冲仍更快");
    printf("  原因：CPU 每块要 %.0fms，而设备只要 %.0fms，多出来的延迟怎么缓冲都消不掉。\n", C2, T);
    printf("结论：缓冲只能掩盖「速度差」，不能突破瓶颈端的处理能力。\n");
    return 0;
}
